import{_ as a,o,c as r,a2 as e}from"./chunks/framework.CXsxtpvq.js";const s="/asset-studio/shots/12-gallery.webp",n="/asset-studio/shots/13-gallery-lightbox.webp",l="/asset-studio/shots/15-gallery-passed.webp",m=JSON.parse('{"title":"갤러리와 검수","description":"","frontmatter":{},"headers":[],"relativePath":"ko/guide/gallery.md","filePath":"ko/guide/gallery.md"}'),i={name:"ko/guide/gallery.md"};function g(p,t,d,h,c,u){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="갤러리와-검수" tabindex="-1">갤러리와 검수 <a class="header-anchor" href="#갤러리와-검수" aria-label="Permalink to &quot;갤러리와 검수&quot;">​</a></h1><p><strong>갤러리</strong>는 <code>outputs/</code> 아래의 모든 이미지를 보여 줍니다. 여기서 이미지를 통과/실패로 검수하고, 통과한 이미지는 내보내거나 LoRA 학습에 씁니다.</p><p><img src="'+s+'" alt="갤러리"></p><h2 id="거르기와-정렬" tabindex="-1">거르기와 정렬 <a class="header-anchor" href="#거르기와-정렬" aria-label="Permalink to &quot;거르기와 정렬&quot;">​</a></h2><p>위쪽에서 캐릭터, 의상, 감정·동작, 구분(일반/성인), 모델 계열로 거릅니다.</p><ul><li><strong>각 항목의 최신 이미지</strong>: 감정마다 가장 최근 이미지만 봅니다.</li><li><strong>내 판정</strong>: 미검수·통과·실패만 봅니다.</li><li><strong>확정 채택만</strong>: 감정마다 채택된 한 장만 봅니다.</li></ul><p>생성한 뒤 갤러리로 돌아왔을 때 마지막으로 본 뒤 새로 생긴 이미지가 있으면 <strong>새 이미지가 있습니다 · 갱신</strong>이 나타납니다.</p><h2 id="이미지-자세히-보기" tabindex="-1">이미지 자세히 보기 <a class="header-anchor" href="#이미지-자세히-보기" aria-label="Permalink to &quot;이미지 자세히 보기&quot;">​</a></h2><p>이미지를 누르면 크게 보이고 오른쪽에 제작 기록(모델, 시드, 프롬프트, 설정)이 나옵니다. ←/→로 넘기고, <strong>100% 보기</strong>로 원본 크기를 봅니다.</p><p><img src="'+n+'" alt="이미지 상세와 제작 기록"></p><p>키보드로 빠르게 검수할 수 있습니다: <strong>P</strong> 통과, <strong>F</strong> 실패, <strong>U</strong> 미검수.</p><h2 id="검수와-채택" tabindex="-1">검수와 채택 <a class="header-anchor" href="#검수와-채택" aria-label="Permalink to &quot;검수와 채택&quot;">​</a></h2><p>카드의 <strong>선택</strong>을 체크하고 <strong>선택 통과</strong>·<strong>선택 실패</strong>를 누르면 여러 장을 한 번에 판정합니다.</p><p><img src="'+l+'" alt="여러 장 통과 처리"></p><p>같은 캐릭터·의상·감정 조합에서 통과한 이미지 중 하나가 <strong>★ 채택</strong>이 됩니다(가장 최근에 통과시킨 것). 채택본은 그 감정의 대표 이미지로, ZIP 내보내기와 LoRA 데이터셋의 기본 선택이 됩니다.</p><h2 id="다시-생성하기" tabindex="-1">다시 생성하기 <a class="header-anchor" href="#다시-생성하기" aria-label="Permalink to &quot;다시 생성하기&quot;">​</a></h2><p><strong>새 시드로 재생성</strong>은 고른 이미지의 제작 기록을 그대로 쓰고 시드만 바꿔 다시 생성합니다. 이미지 도구에서 나중에 고친 내용은 다시 생성에 반영되지 않습니다.</p><h2 id="내보내기" tabindex="-1">내보내기 <a class="header-anchor" href="#내보내기" aria-label="Permalink to &quot;내보내기&quot;">​</a></h2><p><strong>현재 범위 ZIP 내보내기</strong>는 지금 거른 범위에서 감정마다 채택된 한 장씩을 ZIP으로 받습니다. 파일 이름은 <code>&lt;작품&gt;/&lt;캐릭터&gt;/&lt;의상&gt;/&lt;감정&gt;.png</code>입니다. 빠진 감정이 있으면 알려 주고, <strong>누락 제외하고 부분 내보내기</strong>로 있는 것만 받을 수도 있습니다.</p><h2 id="이미지-도구로-보내기" tabindex="-1">이미지 도구로 보내기 <a class="header-anchor" href="#이미지-도구로-보내기" aria-label="Permalink to &quot;이미지 도구로 보내기&quot;">​</a></h2><p>고른 이미지를 <a href="./tools">이미지 도구</a>로 보내 태그 분석, 인페인트, 배경 투명화, 가림 처리를 합니다.</p>',21)])])}const b=a(i,[["render",g]]);export{m as __pageData,b as default};
